() => {
  const result = {
    innerWidth: window.innerWidth,
    innerHeight: window.innerHeight,
    xlBreakpoint: window.innerWidth >= 1280
  };
  // Find the h1 with system name and inspect its siblings
  const h1 = Array.from(document.querySelectorAll('h1')).find(h => h.textContent.includes('智能问数分析系统'));
  if (h1) {
    const parent = h1.parentElement;
    result.h1Text = h1.textContent.trim();
    result.parentHTML = parent ? parent.outerHTML.slice(0, 2000) : null;
    // Look for any element containing 'NL2SQL' or version patterns
    const allText = Array.from(document.querySelectorAll('header * , [class*=badge], [class*=version]'))
      .filter(el => /NL2SQL|v\d+\.\d+\.\d+/i.test(el.textContent || '') && el.children.length === 0)
      .map(el => ({
        tag: el.tagName,
        text: el.textContent.trim(),
        className: el.className,
        visible: el.offsetParent !== null,
        rect: el.getBoundingClientRect().toJSON()
      }));
    result.badgeCandidates = allText;
  } else {
    result.error = 'h1 not found';
  }
  return result;
}

() => {
  window.resizeTo(1600, 1000);
  return new Promise(resolve => {
    setTimeout(() => {
      resolve({ innerWidth: window.innerWidth, innerHeight: window.innerHeight, outerWidth: window.outerWidth, outerHeight: window.outerHeight });
    }, 500);
  });
}

() => {
  const screen = { availWidth: window.screen.availWidth, availHeight: window.screen.availHeight, width: window.screen.width, height: window.screen.height };
  // Move window to far left offscreen and resize very wide
  window.moveTo(0, 0);
  window.resizeTo(2600, 1000);
  return new Promise(resolve => {
    setTimeout(() => {
      resolve({
        screen,
        after: { innerWidth: window.innerWidth, innerHeight: window.innerHeight, outerWidth: window.outerWidth, outerHeight: window.outerHeight, screenX: window.screenX, screenY: window.screenY }
      });
    }, 500);
  });
}

() => {
  const w = window.open('http://localhost:3000', 'verify_wide', 'width=1600,height=1000,left=0,top=0');
  if (!w) return { opened: false };
  return new Promise(resolve => {
    setTimeout(() => {
      try {
        resolve({ opened: true, popupInner: w.innerWidth, popupOuter: w.outerWidth });
      } catch (e) {
        resolve({ opened: true, error: String(e) });
      }
    }, 2000);
  });
}

() => {
  window.resizeTo(900, 700);
  return new Promise(resolve => setTimeout(() => resolve({ innerWidth: window.innerWidth, outerWidth: window.outerWidth, outerHeight: window.outerHeight }), 400));
}

() => {
  const badge = document.querySelector('h1 + span') || Array.from(document.querySelectorAll('span')).find(s => s.textContent.includes('NL2SQL'));
  if (!badge) return { error: 'badge not found' };
  const text = badge.textContent;
  const charCodes = Array.from(text).map(c => c.charCodeAt(0));
  const xlMatches = window.matchMedia('(min-width: 1280px)').matches;
  // Temporarily remove 'hidden' to simulate xl rendering (runtime DOM only, no source change)
  badge.classList.remove('hidden');
  const cs = getComputedStyle(badge);
  const rect = badge.getBoundingClientRect().toJSON();
  return {
    exactText: text,
    charCodes,
    xlMediaQueryMatches: xlMatches,
    viewportWidth: window.innerWidth,
    computed: {
      display: cs.display,
      backgroundColor: cs.backgroundColor,
      color: cs.color,
      borderColor: cs.borderColor,
      borderRadius: cs.borderRadius,
      fontSize: cs.fontSize,
      fontWeight: cs.fontWeight
    },
    rect
  };
}

() => {
  window.focus();
  return new Promise(resolve => setTimeout(() => resolve({ visibilityState: document.visibilityState, hasFocus: document.hasFocus() }), 500));
}

() => {
  const badge = document.querySelector('h1 + span');
  if (badge) badge.classList.remove('hidden');
  window.focus();
  return { visibilityState: document.visibilityState, innerWidth: window.innerWidth, badgeText: badge ? badge.textContent.trim() : null, badgeClass: badge ? badge.className : null };
}

() => {
  const badge = document.querySelector('h1 + span');
  if (badge && !badge.classList.contains('hidden')) badge.classList.add('hidden');
  return { restored: badge ? badge.className.includes('hidden') : null, className: badge ? badge.className : null };
}
